def find_rectangles_of_color(grid, color):
    rects = []
    H, W = len(grid), len(grid[0])

    for tr in range(H):
        for tc in range(W):
            if grid[tr][tc] != color:
                continue

            # Try each possible size
            for height in range(1, H - tr + 1):
                for width in range(1, W - tc + 1):
                    is_rect = True
                    for dr in range(height):
                        for dc in range(width):
                            if grid[tr + dr][tc + dc] != color:
                                is_rect = False
                                break
                        if not is_rect:
                            break

                    if is_rect:
                        area = height * width
                        rects.append((area, tr, tc, height, width))

    seen = set()
    unique = []
    for area, tr, tc, h, w in rects:
        key = (tr, tc, h, w)
        if key not in seen:
            seen.add(key)
            unique.append((area, tr, tc, h, w))

    return sorted(unique, reverse=True, key=lambda x: x[0])

